61	  const { info, slides, proposals } = report.outline;
62	  const lines = [`構成案の書式の誤りは無い (スライド ${String(slides.length)} 枚)`];
63	  lines.push(
64	    info.googleSlides === null
65	      ? `${INFO_LABELS.googleSlides}: 無い`
66	      : `${INFO_LABELS.googleSlides}: ${info.googleSlides.url} (資料の ID: ${info.googleSlides.presentationId})`,
67	  );
68	  lines.push(`${INFO_LABELS.pluginVersion}: ${info.pluginVersion ?? "無い"} (今の版: ${report.currentVersion})`);
69	  lines.push(`${INFO_LABELS.properNouns}: ${info.properNouns ?? "無い"}`);
70	  if (proposals.length > 0) {
71	    lines.push("【提案】が付いたスライド (採否を利用者に質問する):");
72	    for (const s of proposals) lines.push(`  ${String(s.line)} 行目: ${s.key}: ${s.title}`);
73	  }
74	  return `${lines.join("\n")}\n`;
75	}
