77	/** サブコマンド write-info に渡す、書き込む項目。どちらも省略できるが、少なくとも 1 つを指定する */
78	export interface WriteInfoRequest {
79	  /** Google スライドの URL */
80	  readonly googleSlides?: string;
81	  /** true なら、このプラグインの版を書き込む */
82	  readonly pluginVersion?: boolean;
83	}
84	
85	/** サブコマンド write-info の結果。書き込めたら written に書き込んだ行があり、資料の情報に誤りがあれば errors にある */
86	export type WriteInfoReport = { ok: true; written: string[] } | { ok: false; errors: string[] };
87	
88	/**
89	 * 資料のディレクトリの構成案の資料の情報に、Google スライドの URL の行と slide-deck の版の行を書き込む。
90	 * 書き込む行のほかは変えない。題名の行か資料の情報の行に誤りがあれば、ファイルを変えずに誤りを返す。
91	 * URL の形が違うときは、引数の誤りなので ExecutionError を送出する
92	 */
93	export function writeOutlineInfo(
94	  deckDir: string,
95	  request: WriteInfoRequest,
96	  pluginDir: string = PLUGIN_DIR,
97	): WriteInfoReport {
98	  const path = outlinePath(deckDir);
99	  if (request.googleSlides !== undefined) {
100	    const ref = parseGoogleSlidesUrl(request.googleSlides);
101	    if (typeof ref === "string") throw new ExecutionError(ref);
102	  }
103	  const version = request.pluginVersion === true ? pluginVersion(pluginDir) : undefined;
104	  let text = readFileSync(path, "utf8");
105	  const written: string[] = [];
106	  if (request.googleSlides !== undefined) {
107	    const r = writeGoogleSlidesUrl(text, request.googleSlides);
108	    if (!r.ok) return { ok: false, errors: r.errors };
109	    text = r.text;
110	    written.push(`- ${INFO_LABELS.googleSlides}: ${request.googleSlides}`);
111	  }
112	  if (version !== undefined) {
113	    const r = writePluginVersion(text, version);
114	    if (!r.ok) return { ok: false, errors: r.errors };
115	    text = r.text;
116	    written.push(`- ${INFO_LABELS.pluginVersion}: ${version}`);
117	  }
118	  // 両方の行を作り終えてから 1 回だけ書く。片方だけが書き込まれた状態を残さない
119	  writeFileSync(path, text);
120	  return { ok: true, written };
121	}
